import java.util.*;

public class Main {
    static class Edge {
        int y, capacity, flow, cost;
        Edge() {}
        Edge(int y, int capacity, int flow, int cost) {
            this.y = y;
            this.capacity = capacity;
            this.flow = flow;
            this.cost = cost;
        }
    }

    static List<Edge> edges = new ArrayList<>();
    static final int MAX_N = 14043;
    static List<Integer>[] graph = new ArrayList[MAX_N];

    static long total_cost = 0;
    static long[] dist = new long[MAX_N];
    static int[] parent = new int[MAX_N];
    static int[] parent_edge = new int[MAX_N];
    static int[] in_queue = new int[MAX_N];

    static final long INF = (long)1e18;
    static int source = MAX_N - 2;
    static int sink = MAX_N - 1;

    static int remaining(int idx) {
        return edges.get(idx).capacity - edges.get(idx).flow;
    }

    static void augment_flow() {
        for (int i = 0; i < MAX_N; i++) {
            dist[i] = INF;
            parent[i] = -1;
            parent_edge[i] = -1;
            in_queue[i] = 0;
        }
        dist[source] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(source);
        in_queue[source] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            in_queue[u] = 0;
            for (int e_idx : graph[u]) {
                if (remaining(e_idx) == 0) continue;
                Edge e = edges.get(e_idx);
                int y = e.y;
                int cst = e.cost;
                if (dist[y] > dist[u] + cst) {
                    dist[y] = dist[u] + cst;
                    parent[y] = u;
                    parent_edge[y] = e_idx;
                    if (in_queue[y] == 0) {
                        in_queue[y] = 1;
                        q.offer(y);
                    }
                }
            }
        }
        int current = sink;
        while (current != source) {
            int e_idx = parent_edge[current];
            edges.get(e_idx).flow++;
            edges.get(e_idx ^ 1).flow--;
            current = parent[current];
        }
        total_cost += dist[sink];
    }

    static void add_edge(int from, int to, int capacity, int cost) {
        graph[from].add(edges.size());
        edges.add(new Edge(to, capacity, 0, cost));
        graph[to].add(edges.size());
        edges.add(new Edge(from, 0, 0, -cost));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i = 0; i < MAX_N; i++) {
            graph[i] = new ArrayList<>();
        }
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt() - 1;
            add_edge(source, x, 1, 0);
        }

        int tt = 101;
        for (int i = 0; i < tt; i++) {
            add_edge(i * n, sink, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt() - 1;
            int y = sc.nextInt() - 1;
            for (int j = 0; j < tt - 1; j++) {
                add_edge(x + j * n, y + j * n + n, 1, d * (j * 2 + 1));
            }
            for (int j = 0; j < tt - 1; j++) {
                add_edge(y + j * n, x + j * n + n, 1, d * (j * 2 + 1));
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < tt - 1; j++) {
                add_edge(i + j * n, i + j * n + n, k, 0);
            }
        }

        for (int i = 0; i < k; i++) {
            augment_flow();
        }

        System.out.println(total_cost);
        sc.close();
    }
}
